// Define a step size for the particles.
var stepSize = 10;

// Calculate the direction change based on the frame.
var directionChange = Math.floor(time / 20);
// For each particle, determine a direction and adjust its position.
for (var particle of particles) {
    // Use the particle's index and direction change as seed to ensure each particle gets a consistent random direction across frames.
    var seed = particle.uniqueId + directionChange;

    // Get a random direction (0-5) representing the six directions of the hexagon.
    var direction = Math.floor(cavalry.uniform(0, 6, seed));
    // Convert the random direction to an angle (in radians).
    var angle = cavalry.degreesToRadians(direction * 60);

    // Determine the movement in x and y based on the angle and step size.
    var moveX = Math.cos(angle) * stepSize;
    var moveY = Math.sin(angle) * stepSize;

    // Update the particle's position.
    particle.position.x += moveX;
    particle.position.y += moveY;
}

var seconds = Math.floor(time / fps);
if (seconds % 2 == 0) {
    for (let i = 0; i < 5; i++) {
        var particle = {};
        particle.position = {'x': 0, 'y': 0};
        particle.speed = 10;
        particle.angle = (time*10)+cavalry.random(-15, 15, time, i);

        particles.push(particle);
    }
}

