float3 color1 = float3(1.0, 0.0, 0.0); // Red
float3 color2 = float3(0.0, 0.0, 1.0); // Blue

half4 main(float2 coord) {
    float zoom = 0.005;
    float2 pos = coord * zoom;
    float timeFactor = (n0 + 120) / 1000.0;

    for (int index = 1; index < 10; index++) {
        float idx = float(index);
        float fraction = 0.5 / idx;
        float angleX = idx * 3.0 * pos.y;
        float angleY = idx * 3.0 * pos.x;
        pos.x += fraction * cos(angleX) + timeFactor;
        pos.y += fraction * sin(angleY);
    }

    float sumComponents = pos.x + pos.y;

    // Calculate blending factors for each color channel
    float tR = cos(sumComponents) * 0.5 + 0.5;
    float tG = (sin(sumComponents) + sin(sumComponents)) * 0.25 + 0.5;
    float tB = sin(sumComponents) * 0.5 + 0.5;

    // Blend the two colors based on the calculated factors
    float3 finalColor = float3(
        mix(color1.r, color2.r, tR),
        mix(color1.g, color2.g, tG),
        mix(color1.b, color2.b, tB)
    );

    return half4(finalColor, 1.0);
}

uniform shader layer;

// A simple pseudo-random generator based on the pixel coordinate.
half random(half2 co) {
    return fract(sin(dot(co, half2(12.9898, 78.233))) * 43758.5453);
}

half4 main(float2 p) {
    // Apply a scanline effect by modulating brightness along the vertical axis.
    half scan = 0.85 + 0.15 * sin(p.y * 0.05 + n0);

    // Generate a noise value per pixel. Adjusted to range [-1, 1].
    half noise = random(p + n0);
    noise = noise * 2.0 - 1.0;

    // Base sample of the original image.
    half4 baseColor = layer.eval(p);

    // Simulate a chromatic aberration by slightly offsetting red and blue channels.
    half4 redSample  = layer.eval(p + half2(2.0 * noise, 0.0));
    half4 blueSample = layer.eval(p - half2(2.0 * noise, 0.0));

    // Combine channels: red from the offset red sample, green from base, and blue from the offset blue sample.
    half3 color = half3(redSample.r, baseColor.g, blueSample.b);

    // Apply the scanline effect and add a subtle noise overlay.
    color = color * scan + noise * 0.05;
    color = clamp(color, 0.0, 1.0);

    return half4(color, baseColor.a);
}

