// Use a sine wave to displace every point vertically by +/- `amplitude`
var depth = def.highestDepthWithPath(); // This matches the first meshes with geometry.
var pi = 3.14159;
var frequency = 4;
var amplitude = 30;

var meshes = def.getMeshesAtDepth(depth); // Get the meshes at the given depth
var bbox = def.getBoundingBox();
var [minX, maxX] = [bbox.x, bbox.x+bbox.width];

for (var mesh of meshes) {
    var path = mesh.getPathAtIndex(0); // Get the first path in the mesh
    path.resample(5); // Add some extra points so we get a smoother deformation
    var pd = path.pathData(); // get the point data for the path

    for (var idx = 0; idx < pd.length; idx++) {
        if (pd[idx].type == "close") { // skip close verbs, they have no point to move
            continue;
        }
         // we want 'xpos' in the range 0 to 1
        let xpos = cavalry.norm(pd[idx].point.x, minX, maxX);
        // 'displacement' ranges from 'amplitude' to 0
        let displacement = amplitude * (1 - xpos);
        // control start of the sine wave with 'n0' - the attribute below.
        let t = (n0 * 0.1 + xpos * 2 * pi);
        pd[idx].point.y += Math.sin(t * frequency) * displacement;
    }
    // Set the point data
    path.setPathData(pd);
    // Set the path
    mesh.setPathAtIndex(0, path);
}
// Set the mesh
def.setMeshesAtDepth(depth, meshes);
